import {a4Review} from './a4-content.mjs?v=2.8.0';

const originals = {
  H1:{id:'reverse_hyper',name:'Reverse hyper — machine'},
  H2:{id:'bodyweight_horizontal_hip_extension',name:'GHD hip extension — bodyweight'},
};
const comparison = (reviewLabel,cardId,similarity,keeps,changes,check) => {
  const original=originals[reviewLabel.slice(0,2)];
  return {
    group:similarity==='some'?1:2,reviewLabel,originalId:original.id,originalName:original.name,
    cardId,source:'hinges_and_hip_extension',similarity,keeps,changes,check,
    why:keeps,detail:changes,load:check,limited:similarity==='broader',
    basis:`Michael-approved A4 comparison ${reviewLabel}; October 13, 2026`,review:a4Review,
  };
};
